'use strict';

// Text utilities. Small on purpose: the interesting part is the backlog, not the code.

const ACRONYMS = new Set(['API', 'HTTP', 'SQL', 'URL', 'CSS']);

// Cyrillic → Latin, applied after lowercasing so only the lowercase forms need entries.
// Soft/hard signs map to nothing, which is why they are present with an empty value.
const CYRILLIC_TO_LATIN = {
  а: 'a', б: 'b', в: 'v', г: 'g', д: 'd', е: 'e', ё: 'e', ж: 'zh', з: 'z',
  и: 'i', й: 'y', к: 'k', л: 'l', м: 'm', н: 'n', о: 'o', п: 'p', р: 'r',
  с: 's', т: 't', у: 'u', ф: 'f', х: 'h', ц: 'ts', ч: 'ch', ш: 'sh', щ: 'sch',
  ъ: '', ы: 'y', ь: '', э: 'e', ю: 'yu', я: 'ya',
  // Ukrainian/Belarusian letters that show up in otherwise Russian text.
  і: 'i', ї: 'yi', є: 'ye', ґ: 'g', ў: 'u',
};

function transliterate(lowercased) {
  let out = '';
  for (const ch of lowercased) {
    out += Object.prototype.hasOwnProperty.call(CYRILLIC_TO_LATIN, ch) ? CYRILLIC_TO_LATIN[ch] : ch;
  }
  return out;
}

function slugify(input) {
  return transliterate(String(input).trim().toLowerCase())
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function truncate(input, maxLength, suffix = '…', options = {}) {
  const s = String(input);
  if (s.length <= maxLength) return s;
  const budget = Math.max(0, maxLength - suffix.length);
  const hardCut = s.slice(0, budget);
  if (!options.wordBoundary) return hardCut + suffix;

  // Cutting exactly on whitespace already ends on a word boundary; otherwise walk back to the
  // last one that still fits. A single word longer than the budget has no boundary to walk back
  // to — a hard cut beats returning just the suffix.
  const endsOnBoundary = /\s/.test(s[budget] || '');
  const trimmed = endsOnBoundary ? hardCut.replace(/\s+$/, '') : hardCut.replace(/\s\S*$/, '');
  return (trimmed || hardCut) + suffix;
}

function capitalize(input) {
  const s = String(input);
  if (!s) return s;
  return s[0].toUpperCase() + s.slice(1);
}

// Reduce markdown to the text a reader actually sees: link text stays, the URL goes, and syntax
// (emphasis markers, heading hashes, list bullets, quote markers, rules) is not words.
function stripMarkdown(input) {
  return String(input)
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ') // image: a picture, not words
    .replace(/!\[[^\]]*\]\[[^\]]*\]/g, ' ') // reference-style image
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1') // inline link: keep the text
    .replace(/\[([^\]]*)\]\[[^\]]*\]/g, '$1') // reference-style link
    .replace(/^\s*(?:[-*_]\s*){3,}$/gm, ' ') // horizontal rule
    .replace(/^\s{0,3}#{1,6}\s+/gm, '') // heading hashes
    .replace(/^\s*>+\s?/gm, '') // blockquote marker
    .replace(/^\s*(?:[-*+]|\d+[.)])\s+/gm, '') // list bullet / ordered marker
    .replace(/(\*\*|__|~~|\*|_|`)/g, ''); // emphasis, strike, inline code markers
}

function wordCount(input) {
  const s = stripMarkdown(input).trim();
  if (!s) return 0;
  return s.split(/\s+/).length;
}

const WORDS_PER_MINUTE = 200;

// Whole minutes, rounded — 250 words is "1 min", not "2". Rounding is what makes the
// minimum-of-1 meaningful: without it every text under 100 words would read as 0 minutes.
function readingTime(input) {
  const words = wordCount(input);
  if (!words) return 0;
  return Math.max(1, Math.round(words / WORDS_PER_MINUTE));
}

function titleCase(input) {
  return String(input)
    .split(/\s+/)
    .map((w) => (ACRONYMS.has(w.toUpperCase()) ? w.toUpperCase() : capitalize(w.toLowerCase())))
    .join(' ');
}

module.exports = { slugify, truncate, capitalize, wordCount, readingTime, titleCase, ACRONYMS };

