'use strict';
// Tests for the BACKLOG.md items. tests/text.test.js is the pre-existing contract and is not
// touched; everything new lands here.
const test = require('node:test');
const assert = require('node:assert');
const {
  slugify,
  truncate,
  wordCount,
  readingTime,
  escapeHtml,
  titleCase,
  excerpt,
  ACRONYMS,
} = require('../src/text');

test('cyrillic-slug: slugify transliterates Cyrillic to Latin', () => {
  assert.strictEqual(slugify('Привет мир'), 'privet-mir');
  assert.strictEqual(slugify('Ёжик в тумане'), 'ezhik-v-tumane');
  assert.strictEqual(slugify('Съешь ещё'), 'sesh-esche');
  // Latin behaviour is unchanged.
  assert.strictEqual(slugify('Hello World'), 'hello-world');
  assert.strictEqual(slugify('  Spaces  everywhere  '), 'spaces-everywhere');
  // Mixed scripts.
  assert.strictEqual(slugify('Node.js и Мир'), 'node-js-i-mir');
});

test('truncate-word-boundary: opt-in wordBoundary never cuts mid-word', () => {
  const s = 'The quick brown fox jumps';
  // Default behaviour is untouched: hard cut, mid-word.
  assert.strictEqual(truncate(s, 12), 'The quick b…');
  assert.strictEqual(truncate('abcdefghij', 5), 'abcd…');
  // wordBoundary: cut at the last boundary that still fits, then append the suffix.
  assert.strictEqual(truncate(s, 12, '…', { wordBoundary: true }), 'The quick…');
  // The budget boundary itself lands on a space: the whole word is kept.
  assert.strictEqual(truncate(s, 10, '…', { wordBoundary: true }), 'The quick…');
  // Result never exceeds maxLength.
  for (const max of [4, 6, 9, 12, 15, 20]) {
    const out = truncate(s, max, '…', { wordBoundary: true });
    assert.ok(out.length <= max, `len ${out.length} > max ${max} for "${out}"`);
  }
  // Nothing to truncate: unchanged, options or not.
  assert.strictEqual(truncate('short', 20, '…', { wordBoundary: true }), 'short');
  // A custom suffix is accounted for in the budget.
  assert.strictEqual(truncate(s, 14, '...', { wordBoundary: true }), 'The quick...');
  // No boundary fits (one long word): fall back to the hard cut rather than returning nothing.
  assert.strictEqual(truncate('supercalifragilistic', 8, '…', { wordBoundary: true }), 'superca…');
  // wordBoundary: false is explicitly the old behaviour.
  assert.strictEqual(truncate(s, 12, '…', { wordBoundary: false }), 'The quick b…');
});

test('word-count-markdown: counts the words a reader sees', () => {
  // Plain text is unchanged.
  assert.strictEqual(wordCount('one two three'), 3);
  assert.strictEqual(wordCount('   '), 0);
  assert.strictEqual(wordCount(''), 0);
  // Emphasis markers are not words, and do not split the word they wrap.
  assert.strictEqual(wordCount('**bold** text'), 2);
  assert.strictEqual(wordCount('*a* _b_ __c__ ~~d~~ `e`'), 5);
  // Link text counts, the URL does not.
  assert.strictEqual(wordCount('[the docs](https://example.com/a/b/c)'), 2);
  assert.strictEqual(wordCount('See [the docs](https://example.com) for *more* info'), 6);
  // Reference-style links behave the same way.
  assert.strictEqual(wordCount('See [the docs][ref] now'), 4);
  // An image is a picture, not words.
  assert.strictEqual(wordCount('![some alt text](img.png)'), 0);
  // Heading hashes, list bullets and blockquote markers are syntax.
  assert.strictEqual(wordCount('# Heading here'), 2);
  assert.strictEqual(wordCount('### Deeper heading'), 2);
  assert.strictEqual(wordCount('- one\n- two\n- three'), 3);
  assert.strictEqual(wordCount('1. one\n2. two'), 2);
  assert.strictEqual(wordCount('> quoted words here'), 3);
  assert.strictEqual(wordCount('---'), 0);
  // A realistic mixed document.
  const doc = [
    '# Title',
    '',
    'A **short** paragraph with [a link](https://example.com/deep/path) in it.',
    '',
    '- first item',
    '- second item',
  ].join('\n');
  // Title | A short paragraph with a link in it. | first item | second item  = 1 + 8 + 2 + 2
  assert.strictEqual(wordCount(doc), 13);
});

const words = (n) => Array.from({ length: n }, (_, i) => `w${i}`).join(' ');

test('reading-time: whole minutes at 200 wpm, minimum 1 for non-empty', () => {
  assert.strictEqual(readingTime(''), 0);
  assert.strictEqual(readingTime('   '), 0);
  // Any real text is at least a minute.
  assert.strictEqual(readingTime('hello'), 1);
  assert.strictEqual(readingTime(words(1)), 1);
  assert.strictEqual(readingTime(words(199)), 1);
  assert.strictEqual(readingTime(words(200)), 1);
  // Whole minutes, rounded — which is what makes the minimum-1 rule load-bearing.
  assert.strictEqual(readingTime(words(250)), 1);
  assert.strictEqual(readingTime(words(300)), 2);
  assert.strictEqual(readingTime(words(400)), 2);
  assert.strictEqual(readingTime(words(1000)), 5);
  // Always a whole number.
  for (const n of [1, 37, 199, 201, 640]) {
    assert.ok(Number.isInteger(readingTime(words(n))), `not an integer for ${n} words`);
  }
  // Markdown syntax does not inflate the estimate.
  assert.strictEqual(readingTime('# ' + words(150)), readingTime(words(150)));
});

test('escape-html: escapes the five characters, ampersand first', () => {
  assert.strictEqual(escapeHtml(''), '');
  assert.strictEqual(escapeHtml('plain text'), 'plain text');
  assert.strictEqual(escapeHtml('&'), '&amp;');
  assert.strictEqual(escapeHtml('<'), '&lt;');
  assert.strictEqual(escapeHtml('>'), '&gt;');
  assert.strictEqual(escapeHtml('"'), '&quot;');
  assert.strictEqual(escapeHtml("'"), '&#39;');
  // The ampersand of an entity this function itself produces is never escaped twice.
  assert.strictEqual(escapeHtml('a & b < c'), 'a &amp; b &lt; c');
  assert.strictEqual(escapeHtml('<b>'), '&lt;b&gt;');
  // Pre-existing entities in the input are escaped once, as literal text (single pass).
  assert.strictEqual(escapeHtml('&amp;'), '&amp;amp;');
  assert.strictEqual(escapeHtml('&lt;'), '&amp;lt;');
  // A realistic injection attempt.
  assert.strictEqual(
    escapeHtml('<script>alert("xss & \'more\'")</script>'),
    '&lt;script&gt;alert(&quot;xss &amp; &#39;more&#39;&quot;)&lt;/script&gt;'
  );
  // Escaping is idempotent in the sense that output contains no raw special characters left.
  const out = escapeHtml('<a href="x">Tom & Jerry\'s</a>');
  assert.strictEqual(out, '&lt;a href=&quot;x&quot;&gt;Tom &amp; Jerry&#39;s&lt;/a&gt;');
  assert.ok(!/[<>"']/.test(out), 'no raw special characters survive');
});

test('acronyms-configurable: caller can supply their own acronym set', () => {
